 static String english(String value){String direct=EN.get(value);if(direct!=null)return direct;for(String prefix:new String[]{"A guardar ficheiro ","A verificar parte "})if(value.startsWith(prefix))return EN.get(prefix)+value.substring(prefix.length());if(value.matches("[0-9]+ minutos"))return value.substring(0,value.indexOf(' '))+" minutes";for(String separator:new String[]{" · ",": ","\n"}){int i=value.indexOf(separator);if(i>0){return english(value.substring(0,i))+separator+english(value.substring(i+separator.length()));}}return value;}
